<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { ElMessage } from 'element-plus';
import { Search } from 'lucide-vue-next';
import { api } from '../api';
import { post } from '../saas';
import { params, useResponsiveDrawer } from '../province-monitoring';
import { useSessionStore } from '../stores/session';
import { assignmentRoles, assignmentStatuses, clearLocalDraft, dateTime, loadLocalDraft, matterKinds, matterType, newReport, reportError, saveLocalDraft, type InspectionReport } from '../coordination';
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import ProvincePageState from '../components/ProvincePageState.vue';
import InspectionReportFields from '../components/InspectionReportFields.vue';
import '../province-monitoring.css';
import '../coordination.css';
const route=useRoute(),session=useSessionStore(),width=useResponsiveDrawer(920);
const rows=ref<any[]>([]),total=ref(0),page=ref(1),q=ref(''),kind=ref(''),status=ref(''),loading=ref(false),error=ref(''),drawer=ref(false),detail=ref<any>(),detailId=ref(''),detailLoading=ref(false),detailError=ref(''),saving=ref(false),restored=ref(false);
const form=reactive({feedback:'',evidenceNote:'',report:newReport([]) as InspectionReport});
const canHandle=computed(()=>session.user?.roles.some(row=>row.code.startsWith('CITY_ADMIN'))||session.user?.permissions.some(p=>['safety:emergency:respond','safety:alert:handle','safety:emergency:dispatch','safety:violation:write'].includes(p)));
let version=0,detailVersion=0,initializing=false;
const draftKey=()=>`wrc-coordination-feedback:${session.user?.id}:${detailId.value}`;
async function load(){const current=++version;loading.value=true;error.value='';try{const result=await api<any>(`/oversight/city-tasks?${params({page:page.value,pageSize:20,q:q.value.trim(),kind:kind.value,status:status.value})}`);if(current===version){rows.value=result.items;total.value=result.total;}}catch(reason){if(current===version)error.value=reason instanceof Error?reason.message:'省级交办事项读取失败';}finally{if(current===version)loading.value=false;}}
function search(){page.value=1;void load();}
function reset(){q.value=kind.value=status.value='';search();}
function setFeedback(value:any){initializing=true;Object.assign(form,{feedback:value.feedback||'',evidenceNote:value.evidenceNote||'',report:value.report?JSON.parse(JSON.stringify(value.report)):newReport(value.matter.checklist||[])});const draft=value.status==='PROCESSING'?loadLocalDraft(draftKey()):null;restored.value=!!draft;if(draft)Object.assign(form,draft);initializing=false;}
async function open(id:string){const current=++detailVersion;detailId.value=id;drawer.value=true;detail.value=undefined;detailError.value='';detailLoading.value=true;try{const result=await api<any>(`/oversight/city-tasks/${id}`);if(current===detailVersion){detail.value=result;setFeedback(result);}}catch(reason){if(current===detailVersion)detailError.value=reason instanceof Error?reason.message:'办理详情读取失败';}finally{if(current===detailVersion)detailLoading.value=false;}}
async function act(action:'RESPOND'|'SUBMIT'){
 if(!detail.value||saving.value)return;
 if(action==='SUBMIT'){if(form.feedback.trim().length<5){ElMessage.warning('请填写至少5字的办理反馈');return;}if(detail.value.matter.template==='SPECIAL_INSPECTION'){const message=reportError(form.report);if(message){ElMessage.warning(message);return;}}}
 saving.value=true;try{const result=await post<any>(`/oversight/city-tasks/${detail.value.id}/actions`,{action,...(action==='SUBMIT'?{feedback:form.feedback.trim(),evidenceNote:form.evidenceNote,report:detail.value.matter.template==='SPECIAL_INSPECTION'?form.report:undefined}:{})});await load();saving.value=false;detail.value=result;if(action==='RESPOND')setFeedback(result);else{clearLocalDraft(draftKey());restored.value=false;}ElMessage.success(action==='RESPOND'?'已响应省级事项':'办理反馈已提交省级复核');}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'办理未完成，填写内容已保留');}finally{saving.value=false;}
}
watch(form,()=>{if(!initializing&&drawer.value&&detail.value?.status==='PROCESSING')saveLocalDraft(draftKey(),form);},{deep:true,flush:'sync'});
watch(()=>route.query.assignmentId,id=>{if(typeof id==='string')void open(id);},{immediate:true});
void load();
onBeforeUnmount(()=>{version++;detailVersion++;});
</script>
<template><section class="pm-page pm-fill-page coord-city-page"><h1 class="sr-only">省级交办事项</h1><QueryPanel :loading="loading" @search="search" @reset="reset"><QueryField label="关键词" keyword><el-input v-model="q" :prefix-icon="Search" aria-label="事项关键词" clearable placeholder="搜索事项标题或编号"/></QueryField><QueryField label="事项类型"><el-select v-model="kind" aria-label="事项类型" clearable placeholder="全部类型"><el-option v-for="(name,key) in matterKinds" :key="key" :value="key" :label="name"/></el-select></QueryField><QueryField label="办理状态"><el-select v-model="status" aria-label="办理状态" clearable placeholder="全部状态"><el-option v-for="(name,key) in assignmentStatuses" :key="key" :value="key" :label="name"/></el-select></QueryField></QueryPanel>
<ProvincePageState class="pm-fill-body" :loading="loading" :error="error" @retry="load"><section class="pm-list-surface" aria-label="省级交办事项列表"><el-table :data="rows" height="100%" row-key="id" empty-text="暂无符合条件的交办事项"><el-table-column label="事项" min-width="300"><template #default="{row}"><el-button link type="primary" @click="open(row.id)">{{row.matter.title}}</el-button><small class="pm-subline">{{row.matter.businessNo}}</small></template></el-table-column><el-table-column label="类型" width="130"><template #default="{row}"><el-tag effect="plain">{{matterType(row.matter)}}</el-tag></template></el-table-column><el-table-column label="本市分工" width="110"><template #default="{row}">{{assignmentRoles[row.matter.role]}}</template></el-table-column><el-table-column label="完成期限" min-width="170"><template #default="{row}">{{dateTime(row.matter.dueAt)}}</template></el-table-column><el-table-column label="状态" width="140"><template #default="{row}"><el-tag :type="row.status==='CLOSED'?'success':row.status==='SUBMITTED'?'warning':'info'">{{assignmentStatuses[row.status]}}</el-tag></template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row.id)">{{['WAITING','PROCESSING'].includes(row.status)?'办理':'查看'}}</el-button></template></el-table-column></el-table><footer class="pm-pagination"><span>共 {{total}} 条交办事项</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/></footer></section></ProvincePageState>
<el-drawer v-model="drawer" :size="width" title="省级事项办理" class="coord-detail-drawer" :close-on-click-modal="!saving"><ProvincePageState :loading="detailLoading" :error="detailError" @retry="open(detailId)"><template v-if="detail"><header class="coord-detail-heading"><div><p>{{detail.matter.businessNo}} · {{matterType(detail.matter)}}</p><h2>{{detail.matter.title}}</h2></div><el-tag>{{assignmentStatuses[detail.status]}}</el-tag></header><div class="coord-brief"><span>本市分工 <b>{{assignmentRoles[detail.matter.role]}}</b></span><span>完成期限 <b>{{dateTime(detail.matter.dueAt)}}</b></span></div><section class="coord-detail-section"><h3>办理要求</h3><p class="coord-prose">{{detail.matter.description}}</p><p v-if="detail.matter.basis" class="coord-basis">交办依据：{{detail.matter.basis}}</p><p v-if="detail.reviewComment" class="coord-review-comment">省级复核意见：{{detail.reviewComment}}</p></section>
<template v-if="detail.status==='PROCESSING'&&canHandle"><el-alert v-if="restored" title="已恢复当前浏览器中未提交的反馈内容" type="info" :closable="false"/><el-form label-position="top" :disabled="saving"><section v-if="detail.matter.template==='SPECIAL_INSPECTION'" class="coord-detail-section"><h3>专项排查填报</h3><InspectionReportFields v-model="form.report" :checklist="detail.matter.checklist"/><p class="coord-form-note">问题车辆数不得超过排查车辆数，已整改车辆数不得超过问题车辆数。</p></section><el-form-item label="办理反馈" required><el-input v-model="form.feedback" aria-label="办理反馈" type="textarea" :rows="5" maxlength="4000" show-word-limit placeholder="说明核查情况、处理措施和办理结果"/></el-form-item><el-form-item label="证据及材料说明"><el-input v-model="form.evidenceNote" aria-label="证据及材料说明" type="textarea" :rows="3" maxlength="4000" placeholder="填写用于核查的材料名称、编号或相关说明"/></el-form-item></el-form></template>
<section v-else-if="detail.status!=='WAITING'" class="coord-detail-section"><h3>本市办理反馈</h3><InspectionReportFields v-if="detail.report" :model-value="detail.report" :checklist="detail.matter.checklist" readonly/><p class="coord-prose">{{detail.feedback||'尚未提交反馈'}}</p><p v-if="detail.evidenceNote" class="coord-basis">材料说明：{{detail.evidenceNote}}</p></section><section v-else-if="detail.matter.checklist?.length" class="coord-detail-section"><h3>本次检查内容</h3><ol class="coord-plain-checklist"><li v-for="item in detail.matter.checklist" :key="item.id">{{item.label}}</li></ol></section>
<section class="coord-detail-section"><h3>事项过程</h3><el-timeline><el-timeline-item v-for="(log,index) in detail.matter.logs" :key="index" :timestamp="dateTime(log.at)"><p class="coord-prose">{{log.comment||log.content}} · {{log.actorName}}</p></el-timeline-item></el-timeline></section></template></ProvincePageState><template #footer><el-button v-if="detail&&canHandle&&detail.status==='WAITING'" type="primary" :loading="saving" @click="act('RESPOND')">确认响应</el-button><el-button v-else-if="detail&&canHandle&&detail.status==='PROCESSING'" type="primary" :loading="saving" @click="act('SUBMIT')">提交省级复核</el-button><span v-else-if="detail" class="pm-muted">{{detail.status==='SUBMITTED'?'反馈已提交，等待省级复核。':detail.status==='CLOSED'?'事项已办结。':''}}</span></template></el-drawer>
</section></template>
